public:
    int numberOfWays(int n, int m, int k, vector<int>& source, vector<int>& dest) {
        long long mod = 1e9 + 7;
        vector<long long> dp(4, 0);
        if (source == dest) dp[0] = 1;
        else if (source[0] == dest[0]) dp[1] = 1;
        else if (source[1] == dest[1]) dp[2] = 1;
        else dp[3] = 1;
        for (int step = 0; step < k; step++) {
            long long d0 = dp[0], d1 = dp[1], d2 = dp[2], d3 = dp[3];
