    }
};

class Solution {
    public int numberOfWays(int n, int m, int k, int[] source, int[] dest) {
        long mod = 1_000_000_007L;
        long[] dp = new long[4];
        if (source[0] == dest[0] && source[1] == dest[1]) dp[0] = 1;
        else if (source[0] == dest[0]) dp[1] = 1;
        else if (source[1] == dest[1]) dp[2] = 1;
        else dp[3] = 1;
        for (int step = 0; step < k; step++) {
            long d0 = dp[0], d1 = dp[1], d2 = dp[2], d3 = dp[3];
            long n0 = (d1 + d2) % mod;
            long n1 = (d0 * (m - 1) + d1 * (m - 2) + d3) % mod;
            long n2 = (d0 * (n - 1) + d2 * (n - 2) + d3) % mod;
            long n3 = (d1 * (n - 1) + d2 * (m - 1) + d3 * (n + m - 4)) % mod;
            dp[0] = n0;
            dp[1] = n1;
            dp[2] = n2;
            dp[3] = n3;
        }
        return (int) dp[0];
    }
}

/**
 * @param {number} n
 * @param {number} m
 * @param {number} k
 * @param {number[]} source
 * @param {number[]} dest
 * @return {number}
 */
var numberOfWays = function(n, m, k, source, dest) {
    const mod = 1000000007n;
    const bn = BigInt(n), bm = BigInt(m);
    let dp = [0n, 0n, 0n, 0n];
    if (source[0] === dest[0] && source[1] === dest[1]) dp[0] = 1n;
    else if (source[0] === dest[0]) dp[1] = 1n;
    else if (source[1] === dest[1]) dp[2] = 1n;
    else dp[3] = 1n;
    for (let step = 0; step < k; step++) {
        const [d0, d1, d2, d3] = dp;
        const n0 = (d1 + d2) % mod;
        const n1 = (d0 * (bm - 1n) + d1 * (bm - 2n) + d3) % mod;
        const n2 = (d0 * (bn - 1n) + d2 * (bn - 2n) + d3) % mod;
        const n3 = (d1 * (bn - 1n) + d2 * (bm - 1n) + d3 * (bn + bm - 4n)) % mod;
        dp = [n0, n1, n2, n3];
    }
    return Number(dp[0]);
};
